import React from "react";
import "./SecondaryNavbar.css";

const SecondaryNavbar = () => {
  return (
    <div className="secondary-navbar">
      <ul>
        <li>Dashboard</li>
        <li>Profile</li>
        <li>Settings</li>
        <li>Logout</li>
      </ul>
    </div>
  );
};

export default SecondaryNavbar;
